-- 1. Table des Influenceurs et Créateurs de Contenu
CREATE TABLE IF NOT EXISTS public.influencers (
    id BIGSERIAL PRIMARY KEY,
    name TEXT NOT NULL,
    category TEXT NOT NULL DEFAULT 'Micro-influenceur', -- 'Macro-influenceur' | 'Micro-influenceur'
    niche TEXT NOT NULL DEFAULT 'Lifestyle',
    followers TEXT NOT NULL DEFAULT '100K',
    followers_count INTEGER NOT NULL DEFAULT 100000,
    photo TEXT NOT NULL,
    verified BOOLEAN DEFAULT true,
    featured BOOLEAN DEFAULT false,
    engagement_rate TEXT DEFAULT '8.0%',
    bio TEXT,
    socials JSONB DEFAULT '{}'::jsonb,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Index pour recherche rapide
CREATE INDEX IF NOT EXISTS idx_influencers_category ON public.influencers(category);
CREATE INDEX IF NOT EXISTS idx_influencers_niche ON public.influencers(niche);
CREATE INDEX IF NOT EXISTS idx_influencers_followers ON public.influencers(followers_count DESC);

-- 2. Table des Contacts & Demandes de Campagnes (Briefs)
CREATE TABLE IF NOT EXISTS public.contacts (
    id BIGSERIAL PRIMARY KEY,
    company_name TEXT NOT NULL,
    contact_name TEXT NOT NULL,
    email TEXT NOT NULL,
    phone TEXT,
    budget TEXT,
    objective TEXT,
    talent_type TEXT,
    message TEXT NOT NULL,
    file_name TEXT,
    status TEXT DEFAULT 'nouveau', -- 'nouveau' | 'en_cours' | 'traite'
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- 3. Table des Articles & Actualités
CREATE TABLE IF NOT EXISTS public.articles (
    id BIGSERIAL PRIMARY KEY,
    title TEXT NOT NULL,
    slug TEXT UNIQUE NOT NULL,
    excerpt TEXT,
    content TEXT NOT NULL,
    category TEXT,
    read_time TEXT DEFAULT '5 min',
    image TEXT,
    published BOOLEAN DEFAULT true,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Activer Row Level Security (RLS)
ALTER TABLE public.influencers ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.contacts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.articles ENABLE ROW LEVEL SECURITY;

-- Politiques RLS : Lecture publique de tous les influenceurs et articles
CREATE POLICY "Lecture publique influenceurs" ON public.influencers
    FOR SELECT USING (true);

CREATE POLICY "Insertion publique influenceurs" ON public.influencers
    FOR INSERT WITH CHECK (true);

CREATE POLICY "Mise à jour influenceurs" ON public.influencers
    FOR UPDATE USING (true);

CREATE POLICY "Suppression influenceurs" ON public.influencers
    FOR DELETE USING (true);

CREATE POLICY "Lecture publique articles" ON public.articles
    FOR SELECT USING (true);

-- Politiques RLS pour les formulaires de contact
CREATE POLICY "Envoi de brief public" ON public.contacts
    FOR INSERT WITH CHECK (true);

CREATE POLICY "Consultation des briefs" ON public.contacts
    FOR SELECT USING (true);

